PRAGMA foreign_keys = ON;

INSERT OR REPLACE INTO system_context(context_key,category,content,priority,active,updated_at) VALUES
('pwa_canonical_registry','project','CANONICAL PWA REGISTRY: There are exactly three installable PWAs unless Héctor explicitly authorizes a new one: (1) Héctor OS at / owns general UI, chat, shared utilities, Bridge UI and Context UI; (2) Héctor Agent at /agent/ owns autonomous goals, jobs, approvals and Agent controls; (3) Pendientes at /turno-rx/ owns the clinical Piso/RX/TAC/USG workflow and is protected. Héctor Bridge is a shared capability layer owned by Héctor OS: /bridge.html is its canonical UI, /bridge-core.html is an auxiliary console, and /api/hector-bridge is its backend. Context Hub is shared backend/context infrastructure, not a PWA; any UI belongs inside Héctor OS or Bridge by default. Source of truth: config/pwa-registry.json.',5,1,CURRENT_TIMESTAMP),
('pwa_creation_governance','rules','PWA GOVERNANCE: Before creating a new app/page/manifest/service worker, consult config/pwa-registry.json and reuse the registered owner surface when its purpose fits. Authorization to implement a feature is NOT authorization to create a new installable PWA. A new PWA requires explicit user approval specifically for a new PWA and must update the registry in the same change. Backends, brokers, tools, memory layers and consoles attach to an existing owner PWA by default. Never overlap service-worker scopes. Never modify public/turno-rx/ for unrelated work.',5,1,CURRENT_TIMESTAMP),
('cross_agent_coordination','rules','CROSS-AGENT COORDINATION: Before starting a parallel implementation, inspect current main and open PRs for the same capability. Extend or reconcile existing work instead of creating a sibling implementation. If another agent is already building the same capability, share the canonical registry/service and avoid inventing a new PWA or duplicate backend.',5,1,CURRENT_TIMESTAMP);
